import{z as s,x as o,o as B,c as h,q as A,j as i,D as a,d as n,s as l,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Heckscher–Ohlin","description":"","frontmatter":{"title":"Heckscher–Ohlin","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/heckscher-ohlin.md","filePath":"econ/heckscher-ohlin.md","lastUpdated":1791413859000}'),c={name:"econ/heckscher-ohlin.md"};function d(p,E,m,D,f,C){const r=o("Mermaid");return B(),h("div",null,[E[2]||(E[2]=A('<h1 id="heckscher–ohlin" tabindex="-1">Heckscher–Ohlin <a class="header-anchor" href="#heckscher–ohlin" aria-label="Permalink to &quot;Heckscher–Ohlin&quot;">​</a></h1><div class="epigraph"><p>技术相同、偏好相似时，一国出口密集使用其丰裕要素的产品；贸易是要素服务的间接流动，而不必把工人运出国境。</p><footer>—— Heckscher, The Effect of Foreign Trade on the Distribution of Income, 1919；Ohlin, Interregional and International Trade, 1933</footer></div><p><a href="/econ/ricardian-comparative-advantage">上一课</a>用劳动生产率差解释分工。本课缺口是：技术若相同，贸易从哪来？Heckscher–Ohlin（HO）用要素禀赋。Stolper–Samuelson 下一课把价格接到要素报酬；本课先钉 \\(2\\times2\\times2\\) 的出口模式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两国、两商品、两要素（资本与劳动），相同规模报酬不变技术、相同位似偏好。本国资本相对丰裕：\\(K/L\\gt K^*/L^*\\)。商品 1 资本密集。HO 定理：本国出口 1、进口 2。缺口不是再讲李嘉图的 \\(a_{Li}\\)，而是：相对禀赋差 → 封闭时相对要素价格差 → 相对商品价格差 → 贸易方向。要素不能跨境，商品贸易部分替代要素流动。</p><p><span class="marginnote">要素价格均等化（FPE）：自由贸易加要素密集不逆转、两国都生产两种商品，则 \\(w,r\\) 被商品价格钉死，与禀赋无关（在 FPE 集内）。禀赋只定产量，不定要素价格。这是强结论，实证上常破，但逻辑要先有。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>封闭：丰裕要素相对便宜，密集使用它的产品相对便宜。开放：该产品出口，直到商品价格对齐。Rybczynski：禀赋增加、商品价格不变时，密集使用该要素的产品产量升、另一种降——产量调整代替要素价格调整（在 FPE 内）。这是后课增长与移民的对照系。</p><p><span class="marginnote">数字实例：设本国每工人配 5 单位资本，外国只配 1 单位；汽车每辆用 3 单位资本加 1 个工人，服装用 0.5 单位资本加 3 个工人。本国资本多而便宜，造资本密集的汽车相对便宜，于是出口汽车、进口服装。</span></p>',9)),(B(),i(t,null,{default:a(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20END%5B%22%E7%9B%B8%E5%AF%B9%E7%A6%80%E8%B5%8B%22%5D%20--%3E%20AUT%5B%22%E5%B0%81%E9%97%AD%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20AUT%20--%3E%20TRADE%5B%22%E5%87%BA%E5%8F%A3%E4%B8%B0%E8%A3%95%E8%A6%81%E7%B4%A0%E5%AF%86%E9%9B%86%E5%93%81%22%5D%0A%20%20FPE%5B%22%E5%85%B1%E5%90%8C%E5%A4%9A%E6%A0%B7%E5%8C%96%22%5D%20--%3E%20EQ%5B%22%E8%A6%81%E7%B4%A0%E4%BB%B7%E6%A0%BC%E8%A2%AB%E5%95%86%E5%93%81%E4%BB%B7%E9%92%89%E6%AD%BB%22%5D%0A%20%20RYB%5B%22Rybczynski%22%5D%20--%3E%20Q%5B%22%E4%BA%A7%E9%87%8F%E8%B0%83%2C%20%E8%A6%81%E7%B4%A0%E4%BB%B7%E4%B8%8D%E8%B0%83%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"Leontief 悖论：美国出口劳动密集——对 HO 的早期打击。读法包括：人力资本不是简单 \\(L\\)、技术不同（回到李嘉图）、需求差异、要素密集逆转。本课不仲裁数据，只要求：定理的假设清单要对照着读悖论。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"机制是相对稀缺。商品流动带着要素服务。完全 FPE 时，贸易已经把要素价格拉齐，再让劳动移民的增益只剩不可贸易品与集聚——后课 Melitz、经济地理。FPE 失败（专业化到锥外、贸易成本、技术差）时，要素价格仍可差，移民与贸易是互补而不是完全替代。",-1)),E[6]||(E[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：商品贸易是要素服务的「打包邮寄」——资本没法自己跨国搬家，就被浓缩进机器出口；劳动丰裕国把劳动浓缩进服装出口。运走的是商品，真正流动的是裹在里面的要素服务。")],-1)),(B(),i(t,null,{default:a(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRADE%5B%22%E5%95%86%E5%93%81%E8%B4%B8%E6%98%93%3A%20%E8%A6%81%E7%B4%A0%E6%9C%8D%E5%8A%A1%E7%9A%84%E9%97%B4%E6%8E%A5%E6%B5%81%E5%8A%A8%22%5D%20--%3E%20FPE%7B%22%E8%A6%81%E7%B4%A0%E4%BB%B7%E6%A0%BC%E8%83%BD%E5%90%A6%E8%A2%AB%E6%8B%89%E9%BD%90%2C%20%E5%8D%B3%20FPE%20%E6%88%90%E7%AB%8B%3F%22%7D%0A%20%20FPE%20--%20%22%E6%88%90%E7%AB%8B%22%20--%3E%20SUB%5B%22%E8%B4%B8%E6%98%93%E6%9B%BF%E4%BB%A3%E8%A6%81%E7%B4%A0%E6%B5%81%E5%8A%A8%2C%20%E7%A7%BB%E6%B0%91%E5%8E%8B%E5%8A%9B%E5%8F%98%E5%B0%8F%22%5D%0A%20%20FPE%20--%20%22%E4%B8%8D%E6%88%90%E7%AB%8B%3A%20%E9%94%A5%E5%A4%96%E4%B8%93%E4%B8%9A%E5%8C%96%2F%E8%B4%B8%E6%98%93%E6%88%90%E6%9C%AC%2F%E6%8A%80%E6%9C%AF%E5%B7%AE%22%20--%3E%20COMP%5B%22%E8%A6%81%E7%B4%A0%E4%BB%B7%E6%A0%BC%E4%BB%8D%E6%9C%89%E5%B7%AE%2C%20%E7%A7%BB%E6%B0%91%E4%B8%8E%E8%B4%B8%E6%98%93%E4%BA%92%E8%A1%A5%22%5D%0A%20%20SUB%20--%3E%20W%5B%22%E5%B7%A5%E8%B5%84%E4%B8%8E%E5%88%A9%E7%8E%87%E8%B6%8B%E5%90%8C%E6%9D%A5%E8%87%AA%E5%95%86%E5%93%81%E4%BB%B7%2C%20%E4%B8%8D%E9%9D%A0%E7%A7%BB%E6%B0%91%22%5D%0A%20%20COMP%20--%3E%20W2%5B%22%E5%B7%A5%E8%B5%84%E5%B7%AE%E4%BB%8D%E5%9C%A8%2C%20%E4%BA%BA%E5%8F%A3%E4%B8%8E%E8%B5%84%E6%9C%AC%E6%B5%81%E5%8A%A8%E6%9C%89%E5%8A%A8%E5%8A%9B%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<p>与李嘉图：李嘉图是技术差、一种要素；HO 是技术同、多种要素。现实两者都在。不要用 HO 否定比较优势：HO 是比较优势的一种来源（禀赋），不是替代定义。</p><p><span class="marginnote">Ohlin 强调地区间要素流动与商品流动的替代。Heckscher 更早把收入分配写进贸易。Samuelson 把 \\(2\\times2\\) 代数写严。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(2\\times2\\times2\\) 不能直接读成「资本丰裕国只出口机器」。多要素、多商品用 HOV（Vanek）写成要素含量：净出口的要素含量等于禀赋减消费的要素含量。Trefler 的「缺失贸易」：要素含量远小于禀赋差，要技术差与贸易成本。下一课 SS：商品价格变动如何切分 \\(w\\) 与 \\(r\\)，这是分配政治的理论核。</p><p><span class="marginnote">常见误区：把 HO 读成「资本丰裕国只出口资本密集品」。定理给出的是出口结构偏向，且前提苛刻——技术相同、要素密集不逆转、两国都生产两种商品。Leontief 悖论正是提醒：人力资本与技术差都可能把预测翻过来。</span></p><p>后课默认：技术相同时，出口丰裕要素的密集型产品；FPE 是共同多样化的强预测，不是数据默认。李嘉图的技术差与 HO 的禀赋差可以并存。不要用封闭要素价格当自由贸易后的工资。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HO：出口密集使用丰裕要素的产品。</li><li>贸易替代（部分）要素流动；FPE 在锥内钉住 \\(w,r\\)。</li><li>Rybczynski：价格不变时产量随禀赋极端调整。</li><li>Leontief / 缺失贸易对照的是假设，不是「定理算错」。</li><li>出处：Heckscher 1919；Ohlin 1933；Samuelson 的 \\(2\\times2\\)；Vanek；Trefler。</li></ul>',8))])}const F=s(c,[["render",d]]);export{u as __pageData,F as default};
